widget.draw:
function draw(ctx, state, t) {
  var w = state.w;
  var h = state.h;
  var r = state.r;
  var eps = state.eps;
  function fmt(v) { return Math.round(v * 100) / 100; }
  function X(e) { return 48 + e / 2 * 544; }
  function Y(g) { return 272 - g * 224; }
  var gain = r / Math.sqrt(r * r + eps);
  var thr = r * r - eps;
  var thrEps = r * r;
  var thrX = X(0);
  var clipped = 0;
  if (thrEps > 2) { thrX = X(2); clipped = 1; } else { thrX = X(thrEps); }
  var i = 0;
  var e = 0;
  var g = 0;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = "#1d1a16";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(X(0), Y(0));
  ctx.lineTo(X(2), Y(0));
  ctx.moveTo(X(0), Y(0));
  ctx.lineTo(X(0), Y(1));
  ctx.stroke();
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (i = 0; i <= 60; i++) { e = i / 60 * 2; g = r / Math.sqrt(r * r + e); if (i === 0) { ctx.moveTo(X(e), Y(g)); } else { ctx.lineTo(X(e), Y(g)); } }
  ctx.stroke();
  ctx.strokeStyle = "#c4512c";
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (i = 0; i < 14; i++) { ctx.moveTo(thrX, 48 + i * 16); ctx.lineTo(thrX, 48 + i * 16 + 8); }
  ctx.stroke();
  ctx.fillStyle = "#c4512c";
  ctx.beginPath();
  ctx.arc(X(eps), Y(gain), 6, 0, 6.2832);
  ctx.fill();
  ctx.fillStyle = "#1d1a16";
  ctx.font = "13px sans-serif";
  ctx.fillText("gain = " + fmt(gain), 48, 316);
  ctx.fillText("r = " + fmt(state.r), 220, 316);
  ctx.fillText("eps = " + fmt(state.eps), 340, 316);
  ctx.fillText("not to scale", 48, 30);
  ctx.fillText("thr = " + fmt(thr), 470, 316);
  ctx.font = "12px sans-serif";
  ctx.fillStyle = "#8a8175";
  ctx.fillText("eps axis 0 to 2", 48, 340);
  ctx.fillText("gain axis 0 to 1", 340, 340);
  if (clipped === 1) { ctx.fillStyle = "#c4512c"; ctx.fillText("clipped", thrX - 52, 60); }
}
